# COMMAND ----------

spark.sql(r"""
MERGE INTO dbo.dim_patient_enrollment AS tgt
USING (
  SELECT
    patient_id,
    program_code,
    enrollment_status,
    enrolled_date,
    disenrolled_date,
    payer_id,
    case_manager_email
  FROM (
    SELECT
      s.patient_id,
      UPPER(LTRIM(RTRIM(s.program_code))) AS program_code,
      COALESCE(NULLIF(UPPER(LTRIM(RTRIM(s.enrollment_status))), ''), 'PENDING') AS enrollment_status,
      TO_DATE(s.enrolled_on, 'M/d/yyyy') AS enrolled_date,
      CAST(TRY_TO_TIMESTAMP(s.disenrolled_on, 'M/d/yyyy') AS DATE) AS disenrolled_date,
      COALESCE(s.payer_id, -1) AS payer_id,
      LOWER(LTRIM(RTRIM(s.case_manager_email))) AS case_manager_email,
      ROW_NUMBER() OVER (
        PARTITION BY s.patient_id, UPPER(LTRIM(RTRIM(s.program_code)))
        ORDER BY s.loaded_at DESC, s.stg_row_id DESC
      ) AS rn
    FROM dbo.stg_patient_enrollments AS s
    WHERE
      s.load_batch_id = CAST(:load_batch_id AS INT) AND NOT s.program_code IS NULL
  ) AS ranked
  WHERE
    rn = 1
) AS src
ON tgt.patient_id = src.patient_id AND tgt.program_code = src.program_code
WHEN MATCHED AND (
  tgt.enrollment_status <> src.enrollment_status
  OR COALESCE(tgt.disenrolled_date, CAST('1900-01-01' AS DATE)) <> COALESCE(src.disenrolled_date, CAST('1900-01-01' AS DATE))
  OR tgt.payer_id <> src.payer_id
) THEN UPDATE SET
  tgt.enrollment_status = src.enrollment_status,
  tgt.disenrolled_date = src.disenrolled_date,
  tgt.payer_id = src.payer_id,
  tgt.case_manager_email = src.case_manager_email,
  tgt.is_active = CAST(CASE WHEN src.disenrolled_date IS NULL THEN 1 ELSE 0 END AS BOOLEAN),
  tgt.updated_at = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN INSERT (
  patient_id,
  program_code,
  enrollment_status,
  enrolled_date,
  disenrolled_date,
  payer_id,
  case_manager_email,
  is_active,
  created_at,
  updated_at
) VALUES (
  src.patient_id,
  src.program_code,
  src.enrollment_status,
  src.enrolled_date,
  src.disenrolled_date,
  src.payer_id,
  src.case_manager_email,
  CAST(CASE WHEN src.disenrolled_date IS NULL THEN 1 ELSE 0 END AS BOOLEAN),
  CURRENT_TIMESTAMP(),
  CURRENT_TIMESTAMP()
)
""", args={"load_batch_id": load_batch_id})

